-- =====================================================================
-- MiniChef | Banco de Dados Relacional (Oracle)
-- Script 01: criação das tabelas do MVP (banco de origem da C3)
--
-- É o mesmo modelo da C2, escrito para o Oracle da VM da disciplina.
-- O script de migração da C3 lê estas tabelas e cria no MongoDB uma
-- coleção com o mesmo nome de cada tabela (edital, item 4).
--
-- Diferenças em relação ao PostgreSQL:
--   * SERIAL        -> NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY
--   * VARCHAR / TEXT -> VARCHAR2(n CHAR) (modo de preparo até 4000)
--   * DECIMAL(10,2) -> NUMBER(10,2)
--   * BOOLEAN       -> NUMBER(1) com CHECK (0 ou 1)
--   * NOW()         -> SYSTIMESTAMP
--   * ON DELETE RESTRICT não existe no Oracle: sem cláusula, a exclusão
--     do pai com filhos já é bloqueada.
--
-- Colunas marcadas com [FUTURO] aceitam NULL e ficam vazias no MVP.
-- Pode ser executado mais de uma vez: apaga e recria as tabelas.
-- Execução: sqlplus <usuario>/<senha>@<servico> @src/sql/01_create_tables_oracle.sql
-- =====================================================================

BEGIN
    FOR t IN (SELECT table_name
                FROM user_tables
               WHERE table_name IN ('ITEM_LISTA_COMPRAS', 'LISTA_COMPRAS', 'ITEM_PLANNER',
                                    'PLANNER_SEMANAL', 'RECEITA_INGREDIENTE', 'RECEITA',
                                    'INGREDIENTE', 'USUARIO')) LOOP
        EXECUTE IMMEDIATE 'DROP TABLE ' || t.table_name || ' CASCADE CONSTRAINTS PURGE';
    END LOOP;
END;
/

-- ---------------------------------------------------------------------
-- usuario: pessoa cadastrada; autor de receitas e dono de planners
-- ---------------------------------------------------------------------
CREATE TABLE usuario (
    id                NUMBER(10)          GENERATED BY DEFAULT ON NULL AS IDENTITY,
    nome              VARCHAR2(120 CHAR)  NOT NULL,
    email             VARCHAR2(160 CHAR)  NOT NULL,
    email_confirmado  NUMBER(1)           DEFAULT 0 NOT NULL,
    data_nascimento   DATE                NOT NULL,
    cpf               VARCHAR2(14 CHAR)   NOT NULL,
    senha_hash        VARCHAR2(255 CHAR)  NOT NULL,
    tipo_conta        VARCHAR2(30 CHAR)   DEFAULT 'Usuário comum' NOT NULL,
    perfil_acesso     VARCHAR2(30 CHAR)   DEFAULT 'comum' NOT NULL,
    ativo             NUMBER(1)           DEFAULT 1 NOT NULL,      -- [FUTURO] inativar em vez de excluir
    foto_perfil_url   VARCHAR2(255 CHAR),                          -- [FUTURO] avatar
    criado_em         TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_usuario PRIMARY KEY (id),
    CONSTRAINT uk_usuario_email UNIQUE (email),
    CONSTRAINT uk_usuario_cpf UNIQUE (cpf),
    CONSTRAINT ck_usuario_email_conf CHECK (email_confirmado IN (0, 1)),
    CONSTRAINT ck_usuario_ativo CHECK (ativo IN (0, 1)),
    CONSTRAINT ck_usuario_tipo_conta CHECK (tipo_conta IN (
        'Usuário comum', 'Chef de cozinha', 'Hotel', 'Restaurante',
        'Personal Trainer', 'Nutricionista', 'Administrador de eventos', 'Mercado')),
    CONSTRAINT ck_usuario_perfil CHECK (perfil_acesso IN (
        'comum', 'moderador', 'administrador'))
);

-- ---------------------------------------------------------------------
-- ingrediente: catálogo mestre, mantido pelo administrador
-- ---------------------------------------------------------------------
CREATE TABLE ingrediente (
    id                   NUMBER(10)          GENERATED BY DEFAULT ON NULL AS IDENTITY,
    nome                 VARCHAR2(100 CHAR)  NOT NULL,
    categoria            VARCHAR2(50 CHAR),
    unidade_padrao       VARCHAR2(20 CHAR)   NOT NULL,
    validade_media_dias  NUMBER(5),                       -- [FUTURO] despensa
    preco_medio          NUMBER(10,2),                    -- [FUTURO] orçamento
    CONSTRAINT pk_ingrediente PRIMARY KEY (id)
);

-- ---------------------------------------------------------------------
-- receita
-- usuario 1 : N receita (autor)     | exclusão do autor bloqueada
-- usuario 1 : N receita (moderador) | exclusão do moderador bloqueada
-- ---------------------------------------------------------------------
CREATE TABLE receita (
    id                     NUMBER(10)           GENERATED BY DEFAULT ON NULL AS IDENTITY,
    nome                   VARCHAR2(150 CHAR)   NOT NULL,
    porcao_padrao          NUMBER(5)            NOT NULL,
    refeicao_recomendada   VARCHAR2(60 CHAR),
    modo_preparo           VARCHAR2(4000 CHAR)  NOT NULL,
    nacionalidade          VARCHAR2(60 CHAR),
    tempo_medio_gasto_min  NUMBER(5)            NOT NULL,
    finalidade             VARCHAR2(60 CHAR),
    orcamento_estimado     NUMBER(10,2),
    foto_url               VARCHAR2(255 CHAR),               -- [FUTURO]
    link_video             VARCHAR2(255 CHAR),               -- [FUTURO]
    status                 VARCHAR2(20 CHAR)    DEFAULT 'Rascunho' NOT NULL,
    feedback_moderacao     VARCHAR2(4000 CHAR),
    moderador_id           NUMBER(10),                       -- [FUTURO]
    analisado_em           TIMESTAMP,                        -- [FUTURO]
    autor_id               NUMBER(10)           NOT NULL,
    criado_em              TIMESTAMP            DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_receita PRIMARY KEY (id),
    CONSTRAINT fk_receita_autor FOREIGN KEY (autor_id) REFERENCES usuario (id),
    CONSTRAINT fk_receita_moderador FOREIGN KEY (moderador_id) REFERENCES usuario (id),
    CONSTRAINT ck_receita_porcao CHECK (porcao_padrao > 0),
    CONSTRAINT ck_receita_tempo CHECK (tempo_medio_gasto_min > 0),
    CONSTRAINT ck_receita_status CHECK (status IN (
        'Rascunho', 'Em Análise', 'Publicada', 'Recusada', 'Arquivada'))
);

-- ---------------------------------------------------------------------
-- receita_ingrediente: associativa receita N : N ingrediente
-- receita     1 : N receita_ingrediente | ON DELETE CASCADE
-- ingrediente 1 : N receita_ingrediente | exclusão bloqueada
-- ---------------------------------------------------------------------
CREATE TABLE receita_ingrediente (
    id              NUMBER(10)         GENERATED BY DEFAULT ON NULL AS IDENTITY,
    receita_id      NUMBER(10)         NOT NULL,
    ingrediente_id  NUMBER(10)         NOT NULL,
    quantidade      NUMBER(10,2)       NOT NULL,
    unidade         VARCHAR2(20 CHAR)  NOT NULL,
    papel           VARCHAR2(20 CHAR)  NOT NULL,
    visibilidade    VARCHAR2(10 CHAR)  NOT NULL,
    CONSTRAINT pk_receita_ingrediente PRIMARY KEY (id),
    CONSTRAINT fk_ri_receita FOREIGN KEY (receita_id) REFERENCES receita (id) ON DELETE CASCADE,
    CONSTRAINT fk_ri_ingrediente FOREIGN KEY (ingrediente_id) REFERENCES ingrediente (id),
    CONSTRAINT ck_ri_quantidade CHECK (quantidade > 0),
    CONSTRAINT ck_ri_papel CHECK (papel IN ('Principal', 'Secundário', 'Removível', 'Opcional')),
    CONSTRAINT ck_ri_visibilidade CHECK (visibilidade IN ('Público', 'Privado', 'Opcional'))
);

-- ---------------------------------------------------------------------
-- planner_semanal: planejamento de uma semana de um usuário
-- usuario 1 : N planner_semanal | ON DELETE CASCADE
-- ---------------------------------------------------------------------
CREATE TABLE planner_semanal (
    id                  NUMBER(10)    GENERATED BY DEFAULT ON NULL AS IDENTITY,
    usuario_id          NUMBER(10)    NOT NULL,
    semana_inicio       DATE          NOT NULL,
    orcamento_definido  NUMBER(10,2),                 -- [FUTURO]
    CONSTRAINT pk_planner_semanal PRIMARY KEY (id),
    CONSTRAINT fk_planner_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- item_planner: receita planejada para um dia e uma refeição
-- planner_semanal 1 : N item_planner | ON DELETE CASCADE
-- receita         1 : N item_planner | exclusão bloqueada
-- ---------------------------------------------------------------------
CREATE TABLE item_planner (
    id                 NUMBER(10)         GENERATED BY DEFAULT ON NULL AS IDENTITY,
    planner_id         NUMBER(10)         NOT NULL,
    receita_id         NUMBER(10)         NOT NULL,
    dia_semana         VARCHAR2(15 CHAR)  NOT NULL,
    refeicao           VARCHAR2(20 CHAR)  NOT NULL,
    porcoes_desejadas  NUMBER(5)          NOT NULL,
    CONSTRAINT pk_item_planner PRIMARY KEY (id),
    CONSTRAINT fk_ip_planner FOREIGN KEY (planner_id) REFERENCES planner_semanal (id) ON DELETE CASCADE,
    CONSTRAINT fk_ip_receita FOREIGN KEY (receita_id) REFERENCES receita (id),
    CONSTRAINT ck_ip_porcoes CHECK (porcoes_desejadas > 0),
    CONSTRAINT ck_ip_dia CHECK (dia_semana IN (
        'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado', 'domingo')),
    CONSTRAINT ck_ip_refeicao CHECK (refeicao IN ('Café da manhã', 'Almoço', 'Jantar', 'Lanche'))
);

-- ---------------------------------------------------------------------
-- lista_compras: gerada a partir de um planner
-- planner_semanal 1 : N lista_compras | ON DELETE CASCADE
-- ---------------------------------------------------------------------
CREATE TABLE lista_compras (
    id              NUMBER(10)    GENERATED BY DEFAULT ON NULL AS IDENTITY,
    planner_id      NUMBER(10)    NOT NULL,
    total_estimado  NUMBER(10,2),                     -- [FUTURO]
    gerada_em       TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_lista_compras PRIMARY KEY (id),
    CONSTRAINT fk_lista_planner FOREIGN KEY (planner_id) REFERENCES planner_semanal (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- item_lista_compras: ingrediente agregado a comprar
-- lista_compras 1 : N item_lista_compras | ON DELETE CASCADE
-- ingrediente   1 : N item_lista_compras | exclusão bloqueada
-- ---------------------------------------------------------------------
CREATE TABLE item_lista_compras (
    id                NUMBER(10)         GENERATED BY DEFAULT ON NULL AS IDENTITY,
    lista_compras_id  NUMBER(10)         NOT NULL,
    ingrediente_id    NUMBER(10)         NOT NULL,
    quantidade        NUMBER(10,2)       NOT NULL,
    unidade           VARCHAR2(20 CHAR)  NOT NULL,
    custo_estimado    NUMBER(10,2),                    -- [FUTURO]
    comprado          NUMBER(1)          DEFAULT 0 NOT NULL,
    CONSTRAINT pk_item_lista_compras PRIMARY KEY (id),
    CONSTRAINT fk_ilc_lista FOREIGN KEY (lista_compras_id) REFERENCES lista_compras (id) ON DELETE CASCADE,
    CONSTRAINT fk_ilc_ingrediente FOREIGN KEY (ingrediente_id) REFERENCES ingrediente (id),
    CONSTRAINT ck_ilc_quantidade CHECK (quantidade > 0),
    CONSTRAINT ck_ilc_comprado CHECK (comprado IN (0, 1))
);

-- ---------------------------------------------------------------------
-- Índices
-- ---------------------------------------------------------------------
-- Nome de ingrediente único sem diferenciar maiúsculas ('Tomate' = 'tomate')
CREATE UNIQUE INDEX ux_ingrediente_nome   ON ingrediente (LOWER(nome));
CREATE INDEX ix_receita_status            ON receita (status);
CREATE INDEX ix_receita_refeicao          ON receita (refeicao_recomendada);
CREATE INDEX ix_receita_autor             ON receita (autor_id);
CREATE INDEX ix_ri_ingrediente_papel      ON receita_ingrediente (ingrediente_id, papel);
CREATE INDEX ix_ri_receita                ON receita_ingrediente (receita_id);
CREATE INDEX ix_item_planner_planner      ON item_planner (planner_id);
CREATE INDEX ix_lista_planner             ON lista_compras (planner_id);
CREATE INDEX ix_ilc_lista                 ON item_lista_compras (lista_compras_id);
